func TestLockfilesRemainSeparate(t *testing.T) {
	files := map[string][]byte{
		"/one/Pipfile.lock": []byte(`{"default":{"shared":{"version":"==1.0.0"}}}`),
		"/two/Pipfile.lock": []byte(`{"default":{"shared":{"version":"==2.0.0"}}}`),
	}
	wantVersion := map[string]string{
		"/one/Pipfile.lock": "1.0.0",
		"/two/Pipfile.lock": "2.0.0",
	}
	var scannersCount int
	for path, content := range files {
		result, err := analyzer.AnalyzeFile(path, &DummyFileInfo{}, func() ([]byte, error) { return content, nil })
		if err != nil {
			t.Fatal(err)
		}
		scanners, err := convertLibWithScanner(result)
		if err != nil {
			t.Fatal(err)
		}
		scannersCount += len(scanners)
		for _, scanner := range scanners {
			if scanner.Path != path || len(scanner.Libs) != 1 {
				t.Errorf("%s: got scanner %+v", path, scanner)
				continue
			}
			if scanner.Libs[0].Name != "shared" || scanner.Libs[0].Version != wantVersion[path] {
				t.Errorf("%s: got library %+v", path, scanner.Libs[0])
			}
		}
	}
	if scannersCount != 2 {
		t.Fatalf("got %d scanners, want 2", scannersCount)
	}
}
